CREATE TEMPORARY VIEW dwd_search_metrics_${grass_region_without_quote} AS
SELECT
    user_id
    ,global_session_id
    ,page_type
    ,page_section[0] AS page_section
    ,target_type
    ,event_timestamp
    ,original_operation AS operation
    ,LEAD(event_timestamp) OVER (PARTITION BY global_session_id,original_operation ORDER BY event_timestamp) as next_search_time
FROM
    srdi_mart.dwd_sr_data_warehouse_platform
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND user_id > 0
    AND page_type IN ('pre_search')
    AND operation = 'click'
    AND (
      (page_section[0] = 'keyboard' AND target_type = 'mic' AND original_operation = 'click')
      OR
      (original_operation = 'action_voice_search' AND page_section IS NULL AND target_type IS NULL)
    );

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_search_metrics_${grass_region_without_quote} AS
SELECT
    user_id
    ,global_session_id
    ,SUM(IF(operation = 'click' AND page_type = 'pre_search' AND page_section = 'keyboard' AND target_type = 'mic', 1, 0)) AS mic_click_cnt
    ,SUM(IF(operation = 'action_voice_search' AND page_type = 'pre_search' AND page_section IS NULL AND target_type IS NULL, 1, 0)) AS action_voice_search_cnt
    ,SUM(IF(operation = 'action_voice_search' AND page_type = 'pre_search' AND page_section IS NULL AND target_type IS NULL AND 
        next_search_time IS NOT NULL AND (next_search_time - event_timestamp) < 60000, 1, 0)) AS retry_needed_count
FROM
    dwd_search_metrics_${grass_region_without_quote}
GROUP BY
    1,2;

--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_search_global_session_level_metrics_1d
PARTITION (
    grass_region = ${grass_region}
    ,local_date = ${local_date}
)
SELECT
    global_session_id
    ,user_id

    ,mic_click_cnt
    ,action_voice_search_cnt
    ,retry_needed_count
FROM
    dws_search_metrics_${grass_region_without_quote};
